{
  "title": "Same route, changed rule",
  "teaching": "comparison",
  "duration": 8,
  "objects": [
    {
      "id": "route",
      "kind": "line",
      "from": [260, 300],
      "to": [1180, 300],
      "role": "blue",
      "strokeWidth": 2,
      "opacity": 0
    },
    {
      "id": "ship",
      "kind": "circle",
      "cx": 340,
      "cy": 300,
      "r": 9,
      "stroke": "#8bd0df",
      "opacity": 0
    },
    {
      "id": "left",
      "kind": "comparison-card",
      "role": "blue",
      "slots": {
        "title": "1916: restricted attacks",
        "value": "warning required",
        "caption": "Restrictions demanded warning and crew safety",
        "icon": "shield",
        "criteria": [
          {
            "label": "Warning given",
            "value": "yes"
          },
          {
            "label": "Crew safety",
            "value": "protected"
          },
          {
            "label": "Risk to shipping",
            "value": "lower"
          }
        ]
      }
    },
    {
      "id": "right",
      "kind": "comparison-card",
      "role": "coral",
      "slots": {
        "title": "Feb 1917: unrestricted",
        "value": "no warning",
        "caption": "Same neutral route, attacks without warning",
        "icon": "warning",
        "criteria": [
          {
            "label": "Warning given",
            "value": "no"
          },
          {
            "label": "Crew safety",
            "value": "at risk"
          },
          {
            "label": "Risk to shipping",
            "value": "higher"
          }
        ]
      }
    }
  ],
  "actions": [
    {
      "at": 0.2,
      "duration": 0.4,
      "kind": "show",
      "id": "route"
    },
    {
      "at": 0.3,
      "duration": 0.4,
      "kind": "show",
      "id": "ship"
    },
    {
      "at": 1.0,
      "duration": 1.4,
      "kind": "morph",
      "id": "route",
      "to": "left",
      "mode": "replace"
    },
    {
      "at": 1.0,
      "duration": 1.4,
      "kind": "morph",
      "id": "route",
      "to": "right",
      "mode": "copy"
    },
    {
      "at": 2.7,
      "duration": 0.4,
      "kind": "fade",
      "id": "ship",
      "opacity": 0
    },
    {
      "at": 3.8,
      "duration": 0.8,
      "kind": "dock",
      "ids": ["left", "right"],
      "y": 60,
      "scale": 0.8
    }
  ],
  "conclusion": {
    "text": "The route held; the rule raised the risk, but did not declare war.",
    "x": 720,
    "y": 545
  }
}

